// Enforce parameter constraints for background cleaning
// gamma > 0; choose in (0.1, 3.1)
l_float32 gamma = ((l_float32)(*FUZZ_PARAM(unsigned int) % 300) + 10) / 100.0f;  // 0.10..3.09
// black/white target levels, typically 0..255
l_int32 blackval = (l_int32)(*FUZZ_PARAM(unsigned int) % 256);
l_int32 whiteval = (l_int32)(*FUZZ_PARAM(unsigned int) % 256);
// Call target; pixim and pixg are optional but provided here to increase coverage
PIX *pixd = pixCleanBackgroundToWhite(pixs, pixim, pixg, gamma, blackval, whiteval);
if (!pixd) { FUZZ_BAIL(); }
// Output the new image and return all inputs back to the pool

// Simple background normalization with optional guidance maps
PIX *pixd = pixBackgroundNormSimple(pixs, pixim, pixg);
if (!pixd) { FUZZ_BAIL(); }
// Return inputs and output

// Choose positive sampling and smoothing parameters
l_int32 sx = (l_int32)((*FUZZ_PARAM(unsigned int) % 32) + 1);
l_int32 sy = (l_int32)((*FUZZ_PARAM(unsigned int) % 32) + 1);
l_int32 thresh = (l_int32)(*FUZZ_PARAM(unsigned int) % 256);
